                    "sql": "create or replace table maplemonk.website_marketplace_fact_items as With Product_Level_Data as ( select om.* ,case when af_order_id is not null then \'Affiliation\' end as Affiliates ,od.site_product_name ,od.product_name ,od.product_qty ,od.product_pack ,od.cost_price ,case when ifnull(od.unit_equi_pound,0) != 0 then (od.unit_equi_pound * ifnull(product_qty,0)) + ifnull(prod_ship,0) else ifnull(total_price,0)+ ifnull(prod_ship,0) end as Selling_Price_pre ,od.unit_equi_pound * ifnull(product_qty,0) + ifnull(prod_ship,0) as total_price ,case when ifnull(od.prod_vat_amazon,0) != 0 then ifnull(od.prod_vat_amazon,0) else ifnull(od.prod_vat,0) end as TAX ,ifnull(ship_vat,0) as shipping_price ,od.is_pack ,od.status ,od.prod_returned_date ,od.prod_return_qty ,od.returnreason ,od.product_id ,od.product_master_id ,od.other_vat_charge ,od.prod_refund_amount ,od.prod_refund_vat ,od.primary_cat_id ,od.product_code as sku ,del_country as delivery_country ,case when upper(`pg_status`) = \'Y\' AND pg.`mpg_id` = 11 then \'MARKETPLACE\' else \'WEBSITE\' end as Business_Segment ,safe_divide(ifnull(calculated_discount,0), count(*) over(partition by om.order_id)) as calculated_discount_final ,safe_divide(ifnull(additional_added_amount,0), count(*) over(partition by om.order_id)) as additional_amount_pre from( select * ,case when lower(discount_type) like \'%fixed%\' or trim(discount_type) = \'\' then discount else (discount/100) * sub_total end calculated_discount from cc_comfort_db.order_master ) om left join cc_comfort_db.order_details od on od.order_id = om.order_id left join ( SELECT * FROM `cc_comfort_db.payment_gateways` qualify ROW_NUMBER() over(partition by lower(ifnull(gateway_name,\'\')) order by 1) = 1 )pg on lower(pg.gateway_name) = lower(om.payment_gateway) left join ( select order_id as af_order_id from cc_comfort_db.affiliates_network_sales_track_data qualify row_number() over(partition by order_id order by 1) = 1 )aff on aff.af_order_id = om.order_id where not(od.status in (0,25)) ) select pld.order_id ,pld.order_channel ,pld.cust_id ,pld.order_id as reference_code ,coalesce(del_mobile,bill_mobile) as phone ,cast(null as string) as email ,cast(null as string) as name ,date(pld.order_date) as order_date ,timestamp(pld.order_date) as order_timestamp ,date(pld.order_modified_date) as order_modified_date ,currency_name_customer currency_code ,coalesce(del_city,bill_city) as City ,coalesce(del_state,bill_State) as State ,coalesce(del_zipcode,bill_zipcode) zipcode ,upper(coalesce(del_country,bill_country)) as country_name ,Affiliates ,pld.payment_gateway ,delivery_country ,courier_name ,pld.courier_id ,tracking_number as awb ,site_product_name ,sku ,product_name ,product_qty ,product_pack ,cost_price ,Selling_Price_pre ,total_price ,TAX ,pld.calculated_discount_final as discount_pre ,pld.additional_amount_pre ,shipping_price ,is_pack ,status ,prod_returned_date ,prod_return_qty ,returnreason ,product_id ,pld.product_master_id ,other_vat_charge ,prod_refund_amount ,prod_refund_vat ,primary_cat_id ,upper(cd.cd_name) product_category_local_payment ,upper(cd.cm_name) product_category_payment ,pg.pg_status ,pg.mpg_id ,pg.merchant_fee ,pg.marketplaces_commission ,Business_Segment ,case when Business_Segment = \'WEBSITE\' then \'WEBSITE\' else pgmm.Marketplace end as Marketplace ,case when Business_Segment = \'WEBSITE\' then d.brand else pmi.pb_name end as Brand ,pg.mpg_name as mpg_Name_Category ,d.id as domain_id ,upper(d.domain_division) domain_division ,date(op.paid_date) as paid_date ,date(op.dispatched_date) as dispatched_date ,date(op.decline_date) as decline_date ,op.decline_reason ,date(op.refund_date) as refund_date ,op.refund_reason ,op.refund_amount ,op.refund_gateway ,csg.Status_Name Order_Status ,d.name as domain_name ,d.abbr as Region ,category_name.cm_name as Product_Category ,sub_category.cm_name as Product_Sub_Category from Product_Level_Data pld left join( select * from cc_comfort_db.category_domain cd left join ( select * from `cc_comfort_db.category_master` qualify ROW_NUMBER() over(partition by ifnull(cm_id,0) order by 1) = 1 )cm on cm.cm_id = cd.cd_cm_id qualify ROW_NUMBER() over(partition by ifnull(cd_id,0) order by 1) = 1 )cd on cd.cd_id = pld.primary_cat_id left join ( SELECT pg.*,pg_category.mpg_name FROM `cc_comfort_db.payment_gateways` pg left join ( select * from powerbi-425707.cc_comfort_db.master_payment_gateway qualify ROW_NUMBER() over(partition by (ifnull(mpg_id,0)) order by 1) = 1 )pg_category on pg_category.mpg_id = pg.mpg_id qualify ROW_NUMBER() over(partition by lower(ifnull(gateway_name,\'\')) order by 1) = 1 )pg on lower(pg.gateway_name) = lower(pld.payment_gateway) left join ( select payment_gateway,Marketplace from `MAPLEMONK.PaymentGateway_to_Marketplace_mapping` qualify ROW_NUMBER() over(partition by lower(ifnull(payment_gateway,\'\')) order by 1) = 1 )pgmm on lower(pgmm.payment_gateway) = lower(pld.payment_gateway) left join ( select domain_division,name,d.id,default_country_code,group_id,brand,abbr from cc_comfort_db.domains d left join ( select Domain_Name,brand from `MAPLEMONK.Domain_Marketplace_Mapping` qualify ROW_NUMBER() over(partition by lower(ifnull(Domain_Name,\'\')) order by 1) = 1 and lower(Marketplace) = \'website\' )dnm on lower(dnm.Domain_Name) = lower(d.name) left join ( select id,abbr from cc_comfort_db.domains_group qualify ROW_NUMBER() over(partition by (ifnull(id,0)) order by 1) = 1 )dg on dg.id = d.group_id qualify ROW_NUMBER() over(partition by (ifnull(d.id,0)) order by 1) = 1 )d on pld.domain_id = d.id left join ( select * from cc_comfort_db.order_processing qualify ROW_NUMBER() over(partition by (ifnull(order_id,0)) order by 1) = 1 )op on op.order_id = pld.order_id left join ( select * from maplemonk.current_status_mapping csg qualify ROW_NUMBER() over(partition by ifnull(cast(id as int64),0) order by 1) = 1 )csg on cast(csg.id as string) = cast(pld.current_status as string) left join ( select product_master_id ,pb_name from cc_comfort_db.products_master pm left join cc_comfort_db.product_brands pb on lower(cast(pm.pm_pb_brand_id as string)) = lower(cast(pb.pb_brand_id as string)) qualify row_number() over(partition by product_master_id order by 1) = 1 )pmi on lower(cast(pmi.product_master_id as string)) = lower(cast(pld.product_master_id as string)) left join ( select pmc_pm_id ,pmc_type ,cm.cm_name from cc_comfort_db.product_master_category pmc left join cc_comfort_db.category_master cm on pmc.pmc_cm_id = cm.cm_id qualify row_number() over(partition by pmc_pm_id,pmc_type order by pmc_pm_id asc) = 1 )category_name on category_name.pmc_pm_id = pld.product_master_id and lower(category_name.pmc_type) = \'p\' left join ( select pmc_pm_id ,pmc_type ,cm.cm_name from cc_comfort_db.product_master_category pmc left join cc_comfort_db.category_master cm on pmc.pmc_cm_id = cm.cm_id qualify row_number() over(partition by pmc_pm_id,pmc_type order by pmc_pm_id asc) = 1 )sub_category on sub_category.pmc_pm_id = pld.product_master_id and lower(sub_category.pmc_type) = \'s\' ; CREATE OR REPLACE TABLE maplemonk.website_marketplace_fact_items AS Select mc.*, ifnull(mc.additional_amount_pre,0)/ifnull(rh.er_exchange_rate,1) as additional_amount, ifnull(mc.discount_pre,0)/ifnull(rh.er_exchange_rate,1) as Discount, ifnull(selling_price_pre,0) + ifnull((ifnull(mc.additional_amount_pre,0)/ifnull(rh.er_exchange_rate,1)),0) - ifnull((ifnull(mc.discount_pre,0)/ifnull(rh.er_exchange_rate,1)),0) as Selling_Price from maplemonk.website_marketplace_fact_items mc left join `cc_comfort_db.exchange_rate_history` rh on cast(rh.er_date as date) = cast(mc.order_date as date) and upper(mc.currency_code) = upper(rh.er_currency_name) ;",
                    "transaction": true
